package com.bank.settlement.service;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Finds every start index of a complete settlement batch (concatenation of all codes).
public class SettlementMessageScanner {
    private static final Logger log = Logger.getLogger(SettlementMessageScanner.class.getName());

    public List<Integer> findBatchStarts(String message, String[] codes) {
        List<Integer> starts = new ArrayList<>();
        if (message == null || codes == null || codes.length == 0) {
            return starts;
        }
        int L = codes[0].length();
        int count = codes.length;
        int totalLen = L * count;
        if (message.length() < totalLen) {
            return starts;
        }
        Map<String, Integer> need = new HashMap<>();
        for (String c : codes) {
            need.merge(c, 1, Integer::sum);
        }

        // Run the window once per offset 0..L-1 so word boundaries align.
        for (int offset = 0; offset < L; offset++) {
            int left = offset;
            int seenWords = 0;
            Map<String, Integer> seen = new HashMap<>();
            for (int right = offset; right + L <= message.length(); right += L) {
                String word = message.substring(right, right + L);
                if (!need.containsKey(word)) {
                    seen.clear();
                    seenWords = 0;
                    left = right + L;
                    continue;
                }
                seen.merge(word, 1, Integer::sum);
                seenWords++;
                // Drop words from the left until this word is within its quota.
                while (seen.get(word) > need.get(word)) {
                    String leftWord = message.substring(left, left + L);
                    seen.merge(leftWord, -1, Integer::sum);
                    seenWords--;
                    left += L;
                }
                if (seenWords == count) {
                    final int s = left;
                    starts.add(left);
                    log.fine(() -> "Complete batch starts at index " + s);
                    // Slide forward by one word to keep searching.
                    String leftWord = message.substring(left, left + L);
                    seen.merge(leftWord, -1, Integer::sum);
                    seenWords--;
                    left += L;
                }
            }
        }
        log.info(() -> "Batch starts in message for required codes = " + starts);
        return starts;
    }
}
